"use client"

import * as React from "react"
import { Popover as PopoverPrimitive } from "@base-ui/react/popover"

import { cn } from "@/lib/utils"

/*
 * Popover — a floating chrome panel. Dark popover surface, hairline chrome rim,
 * soft drop shadow (shadow-md) so it reads as a raised plate above the canvas.
 */

const PopoverAnchorContext = React.createContext<{
  anchorRef: React.RefObject<HTMLElement | null>
  hasAnchor: boolean
  setHasAnchor: (value: boolean) => void
} | null>(null)

function Popover(props: PopoverPrimitive.Root.Props) {
  const anchorRef = React.useRef<HTMLElement | null>(null)
  const [hasAnchor, setHasAnchor] = React.useState(false)
  const value = React.useMemo(
    () => ({ anchorRef, hasAnchor, setHasAnchor }),
    [hasAnchor]
  )
  return (
    <PopoverAnchorContext.Provider value={value}>
      <PopoverPrimitive.Root {...props} />
    </PopoverAnchorContext.Provider>
  )
}

const PopoverTrigger = PopoverPrimitive.Trigger

const PopoverAnchor = React.forwardRef<
  HTMLDivElement,
  React.ComponentPropsWithoutRef<"div">
>(({ ...props }, ref) => {
  const context = React.useContext(PopoverAnchorContext)
  const localRef = React.useRef<HTMLDivElement | null>(null)
  const mergedRef = React.useCallback(
    (node: HTMLDivElement | null) => {
      localRef.current = node
      if (context) {
        context.anchorRef.current = node
      }
      if (ref instanceof Function) ref(node)
      else if (ref) ref.current = node
    },
    [context, ref]
  )
  React.useEffect(() => {
    if (!context) return
    context.setHasAnchor(true)
    return () => {
      context.setHasAnchor(false)
      if (context.anchorRef.current === localRef.current) {
        context.anchorRef.current = null
      }
    }
  }, [context])
  return <div ref={mergedRef} {...props} />
})
PopoverAnchor.displayName = "PopoverAnchor"

const PopoverContent = React.forwardRef<
  HTMLDivElement,
  PopoverPrimitive.Popup.Props &
    Pick<
      PopoverPrimitive.Positioner.Props,
      "align" | "alignOffset" | "side" | "sideOffset"
    >
>(
  (
    { className, align = "center", alignOffset, side, sideOffset = 6, ...props },
    ref
  ) => {
    const context = React.useContext(PopoverAnchorContext)
    return (
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Positioner
          align={align}
          alignOffset={alignOffset}
          side={side}
          sideOffset={sideOffset}
          anchor={context?.hasAnchor ? context.anchorRef : undefined}
          className="isolate z-50"
        >
          <PopoverPrimitive.Popup
            ref={ref}
            className={cn(
              "origin-(--transform-origin) z-50 w-72 p-4",
              "rounded-lg border border-border",
              "bg-popover text-popover-foreground",
              "[box-shadow:var(--shadow-md)]",
              "outline-none transition-[transform,translate,scale,opacity] duration-base data-starting-style:opacity-0 data-starting-style:scale-95 data-ending-style:opacity-0 data-ending-style:scale-95 data-[side=bottom]:data-starting-style:-translate-y-2 data-[side=left]:data-starting-style:translate-x-2 data-[side=right]:data-starting-style:-translate-x-2 data-[side=top]:data-starting-style:translate-y-2",
              className
            )}
            {...props}
          />
        </PopoverPrimitive.Positioner>
      </PopoverPrimitive.Portal>
    )
  }
)
PopoverContent.displayName = "PopoverContent"

export { Popover, PopoverTrigger, PopoverContent, PopoverAnchor }
